// server/src/services/citationInjector.js

/**
 * Inserts [n] markers into Call 1's text at groundingSupports[].segment.endIndex.
 * Sorts supports descending by endIndex to avoid offset drift.
 * 
 * @param {string} rawText The text generated by Call 1
 * @param {Array} groundingSupports The array from candidates[0].groundingMetadata.groundingSupports
 * @returns {{ markedText: string, presentMarkers: Set<number> }}
 */
export function injectCitationMarkers(rawText, groundingSupports) {
  if (!rawText) return { markedText: '', presentMarkers: new Set() };
  if (!Array.isArray(groundingSupports) || groundingSupports.length === 0) {
    return { markedText: rawText, presentMarkers: new Set() };
  }

  const presentMarkers = new Set();

  // Filter valid supports with endIndex and chunk indices, then sort descending
  const sorted = [...groundingSupports]
    .filter(s => typeof s.segment?.endIndex === 'number' && Array.isArray(s.groundingChunkIndices))
    .sort((a, b) => b.segment.endIndex - a.segment.endIndex);

  let markedText = rawText;

  for (const s of sorted) {
    const idx = s.segment.endIndex;
    if (idx < 0 || idx > markedText.length) continue;

    const validIndices = s.groundingChunkIndices.filter(i => typeof i === 'number');
    if (validIndices.length === 0) continue;

    validIndices.forEach(i => presentMarkers.add(i));
    const markerStr = ' ' + validIndices.map(i => `[${i}]`).join('');
    markedText = markedText.slice(0, idx) + markerStr + markedText.slice(idx);
  }

  return { markedText, presentMarkers };
}
